import 'dart:async';

// flame_audio re-exports audioplayers (AudioPlayer, AudioContext, ...).
import 'package:flame_audio/flame_audio.dart';
import 'package:flutter/foundation.dart';

import '../config/tuning.dart';
import '../profile/player_profile.dart';
import 'landing.dart';

/// Every sound effect, by file (generated by `art/make_sfx.py` into
/// `assets/audio/sfx/`).
enum Sfx {
  landClean('land_clean'),
  landOneFoot('land_onefoot'),
  landCrash('land_crash'),
  limbBreak('limb_break'),
  rocketLaunch('rocket_launch'),
  headDown('head_down'),
  uiClick('ui_click'),
  uiBuy('ui_buy'),
  newBest('new_best');

  const Sfx(this.file);

  final String file;

  /// Path under flame_audio's `assets/audio/` prefix.
  String get path => 'sfx/$file.wav';

  /// The sound for a landing type.
  static Sfx forLanding(LandingType type) => switch (type) {
    LandingType.clean => Sfx.landClean,
    LandingType.oneFoot => Sfx.landOneFoot,
    LandingType.crash => Sfx.landCrash,
  };
}

/// The background music loop (generated by `art/make_music.py`).
const String musicPath = 'music/scrapyard_dusk.wav';

/// The one place that plays sounds: effects at the player's sound-effects
/// volume, and the looping background music at the music volume.
///
/// [Sound.init] is called once at startup. Until then (e.g. in tests)
/// [Sound.play] and [Sound.duckMusic] do nothing, so game and UI code can
/// call them freely.
class Sound {
  Sound._(this._profile);

  static Sound? _instance;

  final PlayerProfile _profile;

  /// The music volume last sent to the player, to skip repeats.
  double? _musicLevel;

  /// True while the music is turned down (head-launch slow motion).
  bool _ducked = false;
  Timer? _duckTimer;

  /// Ambient on iOS: respects the silent switch and lets the player's own
  /// music keep playing. A game sound on Android, no audio focus.
  static AudioContext _audioContext() => AudioContext(
    iOS: AudioContextIOS(category: AVAudioSessionCategory.ambient),
    android: const AudioContextAndroid(
      usageType: AndroidUsageType.game,
      contentType: AndroidContentType.sonification,
      audioFocus: AndroidAudioFocus.none,
    ),
  );

  /// Sets up the audio session, preloads every effect and starts the music.
  static Future<void> init(PlayerProfile profile) async {
    final sound = Sound._(profile);
    _instance = sound;
    try {
      await AudioPlayer.global.setAudioContext(_audioContext());
      await FlameAudio.audioCache.loadAll([
        for (final sfx in Sfx.values) sfx.path,
      ]);
      // Bgm pauses the music when the app goes to the background and
      // resumes it on return.
      await FlameAudio.bgm.initialize(audioContext: _audioContext());
      profile.addListener(sound._updateMusic);
      await sound._updateMusic();
    } on Object catch (e) {
      // No sound is better than no game.
      debugPrint('Sound setup failed: $e');
    }
  }

  /// Starts, stops or re-levels the music to match the settings.
  Future<void> _updateMusic() async {
    final volume = _profile.musicVolume;
    final level =
        volume * Tuning.musicMix * (_ducked ? Tuning.musicDuckShare : 1);
    if (level == _musicLevel) {
      return; // Some other profile change (scrap, best...).
    }
    _musicLevel = level;
    final bgm = FlameAudio.bgm;
    try {
      if (volume <= 0) {
        if (bgm.isPlaying) {
          await bgm.pause();
        }
      } else if (!bgm.isPlaying) {
        if (bgm.audioPlayer.source == null) {
          await bgm.play(musicPath, volume: level);
        } else {
          await bgm.audioPlayer.setVolume(level);
          await bgm.resume();
        }
      } else {
        await bgm.audioPlayer.setVolume(level);
      }
    } on Object catch (e) {
      debugPrint('Music failed: $e');
    }
  }

  /// Turns the music down for [duration] (the head-launch slow motion),
  /// then back up.
  static void duckMusic(Duration duration) {
    final sound = _instance;
    if (sound == null) {
      return;
    }
    sound._duckTimer?.cancel();
    sound._ducked = true;
    unawaited(sound._updateMusic());
    sound._duckTimer = Timer(duration, () {
      sound._ducked = false;
      unawaited(sound._updateMusic());
    });
  }

  /// Plays [sfx] once (does nothing if sound is off or not set up).
  /// [volume] is relative to the player's sound-effects volume.
  static void play(Sfx sfx, {double volume = 1}) {
    final sound = _instance;
    if (sound == null) {
      return;
    }
    final level = (sound._profile.sfxVolume * volume).clamp(0.0, 1.0);
    if (level <= 0) {
      return;
    }
    unawaited(
      FlameAudio.play(sfx.path, volume: level).then<void>(
        (_) {},
        onError: (Object e) => debugPrint('Sound ${sfx.file} failed: $e'),
      ),
    );
  }
}
